def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def isUnivalued(tree):
    vals, left, right = _links(tree)
    if not vals:
        return True
    stack = [0]
    while stack:
        k = stack.pop()
        if vals[k] != vals[0]:
            return False
        if left[k] != -1:
            stack.append(left[k])
        if right[k] != -1:
            stack.append(right[k])
    return True
